from html.parser import HTMLParser
from pathlib import Path
class Check(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.ids=set(); self.refs=[]; self.counts={}
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        self.counts[tag]=self.counts.get(tag,0)+1
        if 'id' in a:
            assert a['id'] not in self.ids, 'Duplicate ID'
            self.ids.add(a['id'])
        if a.get('href','').startswith('#') and a['href'] "'!= '"'#': self.refs.append(a['href'][1:])
        if tag not in {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}: self.stack.append(tag)
    def handle_endtag(self, tag):
        assert self.stack and self.stack.pop()==tag, 'Unbalanced tag: '+tag
    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if self.stack and self.stack[-1]==tag: self.stack.pop()
